examples.template:
MonarchButton({{trigger}}, variant: .secondary) { isMerging = true }
    .sheet(isPresented: $isMerging) {
        MonarchMergeDialog(
            records: [
                MonarchMergeRecord(id: {{records.0.id}}, title: {{records.0.title}}, description: {{records.0.description}}, values: ["name": {{records.0.values.name}}, "email": {{records.0.values.email}}, "phone": {{records.0.values.phone}}, "website": {{records.0.values.website}}, "city": {{records.0.values.city}}]),
                MonarchMergeRecord(id: {{records.1.id}}, title: {{records.1.title}}, description: {{records.1.description}}, values: ["name": {{records.1.values.name}}, "email": {{records.1.values.email}}, "phone": {{records.1.values.phone}}, "website": {{records.1.values.website}}, "city": {{records.1.values.city}}]),
            ],
            fields: [
                MonarchMergeField(id: {{fields.0.id}}, label: {{fields.0.label}}),
                MonarchMergeField(id: {{fields.1.id}}, label: {{fields.1.label}}),
                MonarchMergeField(id: {{fields.2.id}}, label: {{fields.2.label}}),
                MonarchMergeField(id: {{fields.3.id}}, label: {{fields.3.label}}),
                MonarchMergeField(id: {{fields.4.id}}, label: {{fields.4.label}}),
            ],
            consequences: [
                MonarchConsequence(.changed, {{consequences.0}}),
                MonarchConsequence(.changed, {{consequences.1}}),
            ]
        ) { selection in
            kept = selection.primaryID
        }
    }

examples.code:
MonarchButton("Merge duplicates", variant: .secondary) { isMerging = true }
    .sheet(isPresented: $isMerging) {
        MonarchMergeDialog(
            records: [
                MonarchMergeRecord(id: "a", title: "Example Ltd", description: "Created 12 Feb 2025 · 3 projects", values: ["name": "Example Ltd", "email": "hello@example.com", "phone": "", "website": "example.com", "city": "Leeds"]),
                MonarchMergeRecord(id: "b", title: "Example Limited", description: "Created 4 Jun 2025 · 1 invoice", values: ["name": "Example Limited", "email": "hello@example.com", "phone": "+44 20 0000 0000", "website": "example.com", "city": "York"]),
            ],
            fields: [
                MonarchMergeField(id: "name", label: "Name"),
                MonarchMergeField(id: "email", label: "Email"),
                MonarchMergeField(id: "phone", label: "Phone"),
                MonarchMergeField(id: "website", label: "Website"),
                MonarchMergeField(id: "city", label: "City"),
            ],
            consequences: [
                MonarchConsequence(.changed, "1 invoice moves to the kept record."),
                MonarchConsequence(.changed, "The other record is archived, not deleted."),
            ]
        ) { selection in
            kept = selection.primaryID
        }
    }
